public class TelaDeEntrada {
  private final WebDriver driver;

  private final By email = By.id("email");
  private final By senha = By.id("senha");
  private final By entrar = By.id("entrar");

  public TelaDeEntrada(WebDriver driver) {
    this.driver = driver;
  }

  public TelaInicial entrarCom(String usuario, String chave) {
    driver.findElement(email).sendKeys(usuario);
    driver.findElement(senha).sendKeys(chave);
    driver.findElement(entrar).click();
    return new TelaInicial(driver);
  }
}

